```tsx
'use client'; // Required for Next.js App Router

import React, { createContext, useContext, useState, useCallback, ReactNode } from 'react';

// Define the shape of our state
interface TooltipContextType {
  openTooltip: (id: string, content: string, position?: 'top' | 'bottom' | 'left' | 'right') => void;
  closeTooltip: (id: string) => void;
  isOpen: (id: string) => boolean;
}

const TooltipContext = createContext<TooltipContextType | undefined>(undefined);

interface TooltipProviderProps {
  children: ReactNode;
}

export const TooltipProvider: React.FC<TooltipProviderProps> = ({ children }) => {
  // We use a Map to store multiple open tooltips if needed, 
  // or just a single active one. For this example, we track by ID.
  const [activeTooltipId, setActiveTooltipId] = useState<string | null>(null);
  const [tooltipData, setTooltipData] = useState<{
    id: string;
    content: string;
    position: 'top' | 'bottom' | 'left' | 'right';
  } | null>(null);

  const openTooltip = useCallback((id: string, content: string, position: 'top' | 'bottom' | 'left' | 'right' = 'top') => {
    setActiveTooltipId(id);
    setTooltipData({ id, content, position });
  }, []);

  const closeTooltip = useCallback((id: string) => {
    if (activeTooltipId === id) {
      setActiveTooltipId(null);
      setTooltipData(null);
    }
  }, [activeTooltipId]);

  const isOpen = useCallback((id: string) => activeTooltipId === id, [activeTooltipId]);

  return (
    <TooltipContext.Provider value={{ openTooltip, closeTooltip, isOpen }}>
      {children}
    </TooltipContext.Provider>
  );
};

export const useTooltip = () => {
  const context = useContext(TooltipContext);
  if (!context) {
    throw new Error('useTooltip must be used within a TooltipProvider');
  }
  return context;
};
```

